SELECT

FROM evaluation_experiments AS e
WHERE e.organization_uuid = #{organizationUUID}
AND e.workspace_uuid = #{workspaceUUID}
AND e.external_id = #{externalID}

SELECT

FROM evaluation_experiments AS e

    e.organization_uuid = #{params.OrganizationUUID}
    AND e.workspace_uuid = #{params.WorkspaceUUID}

        AND (e.created_at, e.uuid) < (#{params.Cursor.CreatedAt}, #{params.Cursor.UUID})


ORDER BY e.created_at DESC, e.uuid DESC
LIMIT #{params.FetchLimit}

SELECT

FROM evaluation_experiments AS e
WHERE e.organization_uuid = #{params.OrganizationUUID}
AND e.workspace_uuid = #{params.WorkspaceUUID}
AND e.version_external_id = #{params.VersionExternalID}
AND e.evaluator_set_key = #{params.EvaluatorSetKey}
AND e.status = #{params.Status}
ORDER BY e.created_at DESC, e.uuid DESC

mapper.update:
UPDATE evaluation_experiments
SET status = #{params.Status},
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND external_id = #{params.ExternalID}
